INSERT INTO intro_post (
    member_id, title, kind, category, content, match_scope, tags, field, available_time
)
VALUES (
    #{memberId}, #{title}, #{kind}, #{category}, #{content}, #{matchScope}, #{tags}, #{field}, #{availableTime}
)

insert into participation(
    project_id, member_id, project_role, join_status, want_position, motive, contact_email
) values (
    #{projectId}, #{memberId}, #{projectRole}, #{joinStatus}, #{wantPosition}, #{motive}, #{contactEmail}
)

